const fs=require("fs");
const g=require("@cucumber/gherkin");
const {IdGenerator}=require("@cucumber/messages");
const files=fs.readdirSync("features").filter(f=>f.endsWith(".feature")).map(f=>"features/"+f);
let total=0;
for(const f of files){
  const src=fs.readFileSync(f,"utf8");
  const it=g.generateMessages(src,f,"en",new IdGenerator.UUID());
  let errs=0;
  for(const m of it){ if(m.parseError){ console.log("PARSE ERROR in "+f+": "+JSON.stringify(m.parseError.message)); errs++; } }
  if(!errs){
    const doc=it.find(m=>m.gherkinDocument);
    const feats=doc?doc.gherkinDocument.feature:null;
    const sc=(feats&&feats.children||[]).filter(c=>c.scenario).length;
    total+=sc;
    console.log("OK "+f+" -> "+sc+" scenarios");
  }
}
console.log("TOTAL scenarios parsed: "+total);
