cd /home/exedev/shipshape-shakedown/.eval-scratch/P6-cand-hy3/sim && node -e '
const fs=require("fs");
const path=require("path");
// collect scenarios per feature file
const scenarios={};
for(const f of fs.readdirSync("features")){
  if(!f.endsWith(".feature")) continue;
  const p="features/"+f;
  const src=fs.readFileSync(p,"utf8");
  const titles=[...src.matchAll(/^\s*Scenario:\s*(.+?)\s*$/gm)].map(m=>m[1]);
  scenarios[p]=new Set(titles);
}
// verify watchbill references
const w=JSON.parse(fs.readFileSync("watchbill.json","utf8"));
let bad=0, count=0;
for(const k of Object.keys(w)){
  for(const ref of w[k].scenarios){
    const [file,name]=ref.split(/:(.+)/);
    if(!scenarios[file]){ console.log("MISSING FILE: "+ref); bad++; }
    else if(!scenarios[file].has(name)){ console.log("MISSING SCENARIO: "+ref); bad++; }
    else count++;
  }
}
console.log(bad===0 ? "ALL "+count+" watchbill refs resolve to a real scenario" : (bad+" broken refs"));
'
